-- iSmile CRM proposed MySQL 8.0.16+ schema; designed for a Next.js backend.
-- New design based on offline demo, not an existing database dump.
-- IDs are UUID strings generated by application code (crypto.randomUUID).
-- Apply with a migration runner. MySQL DDL implicitly commits; validate in staging.
CREATE DATABASE IF NOT EXISTS ismile_crm CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE ismile_crm;

CREATE TABLE `clinics` (
  id CHAR(36) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  timezone VARCHAR(255) NOT NULL DEFAULT 'Asia/Manila',
  currency char(3) NOT NULL DEFAULT 'PHP',
  settings JSON NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `users` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  full_name VARCHAR(255) NOT NULL,
  email VARCHAR(255) NOT NULL,
  username VARCHAR(255),
  staff_code VARCHAR(255),
  password_hash VARCHAR(255),
  status VARCHAR(255) NOT NULL DEFAULT 'active' CHECK(status IN ('invited','active','suspended','disabled')),
  dentist_code VARCHAR(255),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE(clinic_id,email),
  UNIQUE(clinic_id,staff_code),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `roles` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36),
  code VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  UNIQUE(clinic_id,code),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `user_roles` (
  user_id CHAR(36) NOT NULL,
  role_id CHAR(36) NOT NULL,
  PRIMARY KEY(user_id,role_id),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),
  FOREIGN KEY (`role_id`) REFERENCES `roles`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `permissions` (
  id CHAR(36) PRIMARY KEY,
  resource VARCHAR(255) NOT NULL,
  action VARCHAR(255) NOT NULL,
  UNIQUE(resource,action)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `role_permissions` (
  role_id CHAR(36) NOT NULL,
  permission_id CHAR(36) NOT NULL,
  PRIMARY KEY(role_id,permission_id),
  FOREIGN KEY (`role_id`) REFERENCES `roles`(`id`),
  FOREIGN KEY (`permission_id`) REFERENCES `permissions`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `user_permission_overrides` (
  user_id CHAR(36) NOT NULL,
  permission_id CHAR(36) NOT NULL,
  decision VARCHAR(255) NOT NULL CHECK(decision IN ('allow','deny')),
  PRIMARY KEY(user_id,permission_id),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),
  FOREIGN KEY (`permission_id`) REFERENCES `permissions`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `permission_requests` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  requested_by CHAR(36) NOT NULL,
  resource VARCHAR(255) NOT NULL,
  action VARCHAR(255) NOT NULL DEFAULT 'read',
  tab_code VARCHAR(255),
  justification TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined')),
  decided_by CHAR(36),
  decided_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`requested_by`) REFERENCES `users`(`id`),
  FOREIGN KEY (`decided_by`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `security_sessions` (
  id CHAR(36) PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  refresh_token_hash VARCHAR(255) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  revoked_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `audit_logs` (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  actor_id CHAR(36),
  action VARCHAR(255) NOT NULL,
  entity_type VARCHAR(255) NOT NULL,
  entity_id CHAR(36),
  before_data JSON,
  after_data JSON,
  ip VARCHAR(45),
  occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`actor_id`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `contacts` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  contact_type VARCHAR(255) NOT NULL CHECK(contact_type IN ('patient','lead','guardian','partner','other')),
  full_name VARCHAR(255) NOT NULL,
  email VARCHAR(255),
  phone VARCHAR(255),
  preferred_channel VARCHAR(255),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `patients` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  contact_id CHAR(36) NOT NULL UNIQUE,
  patient_no VARCHAR(255) NOT NULL,
  dob date,
  sex VARCHAR(255),
  medical_alerts TEXT,
  primary_dentist_id CHAR(36),
  status VARCHAR(255) NOT NULL DEFAULT 'active',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE(clinic_id,patient_no),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`contact_id`) REFERENCES `contacts`(`id`),
  FOREIGN KEY (`primary_dentist_id`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `patient_guardians` (
  patient_id CHAR(36) NOT NULL,
  guardian_contact_id CHAR(36) NOT NULL,
  relationship VARCHAR(255),
  is_primary BOOLEAN NOT NULL DEFAULT false,
  PRIMARY KEY(patient_id,guardian_contact_id),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`),
  FOREIGN KEY (`guardian_contact_id`) REFERENCES `contacts`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `lead_sources` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  name VARCHAR(255) NOT NULL,
  UNIQUE(clinic_id,name),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `leads` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  contact_id CHAR(36) NOT NULL,
  source_id CHAR(36),
  assigned_to CHAR(36),
  stage VARCHAR(255) NOT NULL DEFAULT 'new',
  interested_service_id CHAR(36),
  converted_patient_id CHAR(36),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  converted_at DATETIME(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`contact_id`) REFERENCES `contacts`(`id`),
  FOREIGN KEY (`source_id`) REFERENCES `lead_sources`(`id`),
  FOREIGN KEY (`assigned_to`) REFERENCES `users`(`id`),
  FOREIGN KEY (`converted_patient_id`) REFERENCES `patients`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `lead_activities` (
  id CHAR(36) PRIMARY KEY,
  lead_id CHAR(36) NOT NULL,
  actor_id CHAR(36),
  activity_type VARCHAR(255) NOT NULL,
  content TEXT,
  occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`lead_id`) REFERENCES `leads`(`id`),
  FOREIGN KEY (`actor_id`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `service_catalog` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  code VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  price DECIMAL(12,2) NOT NULL CHECK(price>=0),
  duration_minutes int CHECK(duration_minutes>0),
  tax_type VARCHAR(255) NOT NULL DEFAULT 'exempt',
  active BOOLEAN NOT NULL DEFAULT true,
  UNIQUE(clinic_id,code),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

ALTER TABLE `leads` ADD CONSTRAINT `leads_interested_service_fkey` FOREIGN KEY (`interested_service_id`) REFERENCES `service_catalog`(`id`);
CREATE TABLE `appointment_chairs` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  name VARCHAR(255) NOT NULL,
  UNIQUE(clinic_id,name),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `appointments` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  patient_id CHAR(36) NOT NULL,
  dentist_id CHAR(36),
  chair_id CHAR(36),
  service_id CHAR(36),
  starts_at DATETIME(3) NOT NULL,
  ends_at DATETIME(3) NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'booked' CHECK(status IN ('booked','confirmed','checked_in','in_progress','completed','cancelled','no_show')),
  booking_source VARCHAR(255),
  notes TEXT,
  created_by CHAR(36),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CHECK(ends_at>starts_at),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`),
  FOREIGN KEY (`dentist_id`) REFERENCES `users`(`id`),
  FOREIGN KEY (`chair_id`) REFERENCES `appointment_chairs`(`id`),
  FOREIGN KEY (`service_id`) REFERENCES `service_catalog`(`id`),
  FOREIGN KEY (`created_by`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE INDEX appointments_calendar_idx ON appointments(clinic_id,starts_at,dentist_id);
CREATE TABLE `encounters` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  patient_id CHAR(36) NOT NULL,
  appointment_id CHAR(36),
  dentist_id CHAR(36),
  occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  notes TEXT,
  diagnosis TEXT,
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`),
  FOREIGN KEY (`appointment_id`) REFERENCES `appointments`(`id`),
  FOREIGN KEY (`dentist_id`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `treatment_plans` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  patient_id CHAR(36) NOT NULL,
  dentist_id CHAR(36),
  status VARCHAR(255) NOT NULL DEFAULT 'draft',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`),
  FOREIGN KEY (`dentist_id`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `treatment_items` (
  id CHAR(36) PRIMARY KEY,
  plan_id CHAR(36) NOT NULL,
  service_id CHAR(36) NOT NULL,
  tooth_code VARCHAR(255),
  qty DECIMAL(10,2) NOT NULL DEFAULT 1,
  quoted_unit_price DECIMAL(12,2) NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'planned',
  encounter_id CHAR(36),
  FOREIGN KEY (`plan_id`) REFERENCES `treatment_plans`(`id`),
  FOREIGN KEY (`service_id`) REFERENCES `service_catalog`(`id`),
  FOREIGN KEY (`encounter_id`) REFERENCES `encounters`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `clinical_files` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  patient_id CHAR(36) NOT NULL,
  encounter_id CHAR(36),
  object_key VARCHAR(255) NOT NULL,
  mime_type VARCHAR(255) NOT NULL,
  filename VARCHAR(255) NOT NULL,
  uploaded_by CHAR(36),
  uploaded_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`),
  FOREIGN KEY (`encounter_id`) REFERENCES `encounters`(`id`),
  FOREIGN KEY (`uploaded_by`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `payers` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  name VARCHAR(255) NOT NULL,
  payer_type VARCHAR(255) NOT NULL CHECK(payer_type IN ('self','hmo','philhealth','other')),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `invoices` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  patient_id CHAR(36) NOT NULL,
  payer_id CHAR(36),
  number VARCHAR(255) NOT NULL,
  issued_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  status VARCHAR(255) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','part_paid','paid','void')),
  subtotal DECIMAL(12,2) NOT NULL DEFAULT 0,
  tax_total DECIMAL(12,2) NOT NULL DEFAULT 0,
  grand_total DECIMAL(12,2) NOT NULL DEFAULT 0,
  created_by CHAR(36),
  UNIQUE(clinic_id,number),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`),
  FOREIGN KEY (`payer_id`) REFERENCES `payers`(`id`),
  FOREIGN KEY (`created_by`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `invoice_items` (
  id CHAR(36) PRIMARY KEY,
  invoice_id CHAR(36) NOT NULL,
  service_id CHAR(36),
  description TEXT NOT NULL,
  qty DECIMAL(10,2) NOT NULL CHECK(qty>0),
  unit_price DECIMAL(12,2) NOT NULL,
  tax_type VARCHAR(255) NOT NULL,
  line_total DECIMAL(12,2) NOT NULL,
  FOREIGN KEY (`invoice_id`) REFERENCES `invoices`(`id`),
  FOREIGN KEY (`service_id`) REFERENCES `service_catalog`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `payments` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  patient_id CHAR(36),
  amount DECIMAL(12,2) NOT NULL CHECK(amount>0),
  method VARCHAR(255) NOT NULL,
  reference VARCHAR(255),
  received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  status VARCHAR(255) NOT NULL DEFAULT 'posted',
  recorded_by CHAR(36),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`),
  FOREIGN KEY (`recorded_by`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `payment_allocations` (
  id CHAR(36) PRIMARY KEY,
  payment_id CHAR(36) NOT NULL,
  invoice_id CHAR(36) NOT NULL,
  amount DECIMAL(12,2) NOT NULL CHECK(amount>0),
  UNIQUE(payment_id,invoice_id),
  FOREIGN KEY (`payment_id`) REFERENCES `payments`(`id`),
  FOREIGN KEY (`invoice_id`) REFERENCES `invoices`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `payment_plans` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  patient_id CHAR(36) NOT NULL,
  invoice_id CHAR(36),
  status VARCHAR(255) NOT NULL DEFAULT 'active',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`),
  FOREIGN KEY (`invoice_id`) REFERENCES `invoices`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `payment_installments` (
  id CHAR(36) PRIMARY KEY,
  plan_id CHAR(36) NOT NULL,
  due_on date NOT NULL,
  amount DECIMAL(12,2) NOT NULL CHECK(amount>0),
  status VARCHAR(255) NOT NULL DEFAULT 'due',
  FOREIGN KEY (`plan_id`) REFERENCES `payment_plans`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `claims` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  invoice_id CHAR(36) NOT NULL,
  payer_id CHAR(36) NOT NULL,
  claim_no VARCHAR(255),
  status VARCHAR(255) NOT NULL DEFAULT 'draft',
  submitted_at DATETIME(3),
  approved_amount DECIMAL(12,2),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`invoice_id`) REFERENCES `invoices`(`id`),
  FOREIGN KEY (`payer_id`) REFERENCES `payers`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `invoice_void_requests` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  invoice_id CHAR(36) NOT NULL,
  requested_by CHAR(36) NOT NULL,
  reason TEXT NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined')),
  decided_by CHAR(36),
  decided_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`invoice_id`) REFERENCES `invoices`(`id`),
  FOREIGN KEY (`requested_by`) REFERENCES `users`(`id`),
  FOREIGN KEY (`decided_by`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `bank_accounts` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  label VARCHAR(255) NOT NULL,
  last_four VARCHAR(255),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `bank_transactions` (
  id CHAR(36) PRIMARY KEY,
  bank_account_id CHAR(36) NOT NULL,
  posted_on date NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  description TEXT,
  matched_payment_id CHAR(36),
  FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts`(`id`),
  FOREIGN KEY (`matched_payment_id`) REFERENCES `payments`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `expense_entries` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  category VARCHAR(255) NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  incurred_on date NOT NULL,
  description TEXT,
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `conversations` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  contact_id CHAR(36) NOT NULL,
  channel VARCHAR(255) NOT NULL,
  assigned_to CHAR(36),
  status VARCHAR(255) NOT NULL DEFAULT 'open',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`contact_id`) REFERENCES `contacts`(`id`),
  FOREIGN KEY (`assigned_to`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `messages` (
  id CHAR(36) PRIMARY KEY,
  conversation_id CHAR(36) NOT NULL,
  direction VARCHAR(255) NOT NULL CHECK(direction IN ('in','out')),
  sender_user_id CHAR(36),
  body TEXT,
  provider_message_id VARCHAR(255),
  sent_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  delivery_status VARCHAR(255),
  FOREIGN KEY (`conversation_id`) REFERENCES `conversations`(`id`),
  FOREIGN KEY (`sender_user_id`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `automation_rules` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  rule_type VARCHAR(255) NOT NULL,
  enabled BOOLEAN NOT NULL DEFAULT false,
  config JSON NOT NULL,
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `automation_jobs` (
  id CHAR(36) PRIMARY KEY,
  rule_id CHAR(36),
  patient_id CHAR(36),
  scheduled_for DATETIME(3) NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'pending',
  dedupe_key VARCHAR(255) NOT NULL UNIQUE,
  attempts int NOT NULL DEFAULT 0,
  FOREIGN KEY (`rule_id`) REFERENCES `automation_rules`(`id`),
  FOREIGN KEY (`patient_id`) REFERENCES `patients`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `integration_accounts` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  provider VARCHAR(255) NOT NULL,
  config JSON NOT NULL,
  credential_secret_ref VARCHAR(255),
  status VARCHAR(255) NOT NULL DEFAULT 'inactive',
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `approval_requests` (
  id CHAR(36) PRIMARY KEY,
  clinic_id CHAR(36) NOT NULL,
  request_type VARCHAR(255) NOT NULL,
  subject_type VARCHAR(255) NOT NULL,
  subject_id CHAR(36),
  payload JSON NOT NULL,
  requested_by CHAR(36) NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'pending',
  decided_by CHAR(36),
  decided_at DATETIME(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (`clinic_id`) REFERENCES `clinics`(`id`),
  FOREIGN KEY (`requested_by`) REFERENCES `users`(`id`),
  FOREIGN KEY (`decided_by`) REFERENCES `users`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE INDEX contacts_search_idx ON contacts(clinic_id,full_name);
CREATE INDEX invoice_patient_idx ON invoices(clinic_id,patient_id,issued_at);
